protected Set<FType> computeTransitiveComprises() {
    Set<FType> res = new BASet<FType>(FType.comparator);
    if (comprises == null) {
        res.add(this);
    } else {
        for (FType c : comprises) {
            res.addAll(c.getTransitiveComprises());
        }
    }
    return res;
