      if ((nat && fitsNat) || (int && fitsInt) || (!nat && !int && (fitsNat || fitsInt))) None
      else outOfRange(v.toString)
    case SIntArg(_, _, e) => uncomputed(foldSize(e)).flatMap(b => outOfRange(b.toString))
    case _ => None
  }
}

